import matplotlib.pyplot as plt
import numpy as np

dict_pvalues = {'A/A': pvalues, 'A/B': pvalues}

def histogram_pvalue_distribution(pvalues):
    # Построение гистограммы для массива distribution
    plt.hist(pvalues, bins=30, alpha=0.7, color='blue')
    plt.xlabel('Значение')
    plt.ylabel('Частота')
    plt.title('Гистограмма распределения')
    plt.show()

def plot_pvalue_distribution(dict_pvalues):
    """Рисует графики распределения p-value."""
    X = np.linspace(0, 1, 1000)
    for name, pvalues in dict_pvalues.items():
        Y = [np.mean(pvalues < x) for x in X]
        plt.plot(X, Y, label=name)

    plt.plot([0, 1], [0, 1], '--k', alpha=0.8)
    plt.title('Оценка распределения p-value', size=16)
    plt.xlabel('p-value', size=12)
    plt.legend(fontsize=12)
    plt.grid()
    plt.show()
    
plot_pvalue_distribution(dict_pvalues)
